using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioLayerBundleOperations:RefCounted
{
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var v)?v:fallback;
    private static string S(Settings d,string key,string fallback="")=>Get(d,key,fallback).AsString();
    private static double N(Settings d,string key,double fallback=0)=>Get(d,key,fallback).AsDouble();
    private static GArray Items(GodotObject o,string key)=>o.Get(key).AsGodotArray();
    private static Settings Failure(string error)=>new(){["error"]=error};
    private static string Id(){using var crypto=new Crypto();return Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant();}
    private static void Append(GArray target,GArray source){foreach(var raw in source)target.Add(raw);}
    private static void SourceTiming(GodotObject actor,GodotObject document,AudioEditSessionOperations edits){if(!edits.is_note_source(actor))return;var values=actor.Get("values").AsGodotDictionary();values[new StringName("source_bpm")]=edits.note_source_tempo(actor,document);var meter=edits.note_source_meter(actor,document);values[new StringName("source_meter")]=new GArray{meter.X,meter.Y};}
    public Settings selected(RefCounted document,GArray ids)
    {
        if(ids.Count==0)return Failure("Select clips to save as a layer bundle.");var copy=document.Call("snapshot").As<Resource>();double first=double.PositiveInfinity;var required=new System.Collections.Generic.HashSet<string>();foreach(var id in ids){var clip=copy.Call("clip_for_id",id.AsString()).AsGodotObject();if(clip==null)return Failure("A selected clip no longer exists.");first=Math.Min(first,clip.Get("start_time").AsDouble());required.Add(S(copy.Call("track_for_clip",id.AsString()).AsGodotDictionary(),"id"));}var pending=new System.Collections.Generic.Stack<string>(required);while(pending.Count>0){var track=copy.Call("track_for_id",pending.Pop()).AsGodotDictionary();var targets=new System.Collections.Generic.List<string>{S(track,"output"),S(track,"group")};foreach(var send in Get(track,"sends",new GArray()).AsGodotArray())targets.Add(S(send.AsGodotDictionary(),"target"));foreach(string target in targets)if(target.Length>0&&required.Add(target))pending.Push(target);}
        var clips=Items(copy,"clips");var actors=Items(copy,"actors");for(int i=clips.Count-1;i>=0;i--)if(!ids.Contains(clips[i].AsGodotObject().Get("id"))){clips.RemoveAt(i);actors.RemoveAt(i);}using var edits=new AudioEditSessionOperations();foreach(var raw in clips){var clip=raw.AsGodotObject();clip.Set("start_time",clip.Get("start_time").AsDouble()-first);SourceTiming(copy.Call("actor_for_clip",clip.Get("id")).AsGodotObject(),document,edits);}var kept=new GArray();using var lanes=new AudioAutomationLaneOperations();foreach(var raw in Items(copy,"tracks")){var track=raw.AsGodotDictionary();foreach(string key in new[]{"frozen_track","frozen_source","freeze_members","freeze_previous_mute","freeze_previous_locked","freeze_previous_solo"})track.Remove(key);track["locked"]=false;string problem=rebase_owner(track,first);if(problem.Length>0&&required.Contains(S(track,"id")))return Failure(problem);foreach(var effect in Get(track,"effects",new GArray()).AsGodotArray()){problem=rebase_owner(effect.AsGodotDictionary(),first);if(problem.Length>0&&required.Contains(S(track,"id")))return Failure(problem);}if(required.Contains(S(track,"id"))&&!lanes.is_lane(track))kept.Add(track);}var tracks=Items(copy,"tracks");tracks.Clear();Append(tracks,kept);Items(copy,"takes").Clear();copy.Set("scene_binding",new Settings());copy.Set("workspace_state",new Settings());copy.Set("portable_media",new Settings());copy.Set("output_path","");copy.ResourcePath="";foreach(string field in new[]{"sections","chords","tempo_points","meter_points"})Items(copy,field).Clear();copy.Set("composer_settings",new Settings());copy.Set("presets",new Settings());return new Settings{["error"]="",["document"]=copy};
    }
    public string insert(RefCounted session,RefCounted bundle,double at)
    {
        if(bundle==null||!double.IsFinite(at)||at<0||session.Get("_before").AsGodotObject()!=null)return "Finish the current adjustment and choose a valid bundle.";var errors=bundle.Call("validate").AsStringArray();if(errors.Length>0)return string.Join("\n",errors);if(Items(bundle,"clips").Count>512||Items(bundle,"tracks").Count>128)return "A layer bundle supports at most 512 clips and 128 tracks.";var copy=bundle.Call("snapshot").As<RefCounted>();var ids=new Settings();foreach(var raw in Items(copy,"tracks"))ids[S(raw.AsGodotDictionary(),"id")]=Id();foreach(string field in new[]{"actors","clips"})foreach(var raw in Items(copy,field))ids[raw.AsGodotObject().Get("id")]=Id();
        void ShiftCurves(Settings owner){foreach(var raw in Get(owner,"automation",new Settings()).AsGodotDictionary().Values)foreach(var pointRaw in raw.AsGodotArray()){var point=pointRaw.AsGodotDictionary();point["time"]=N(point,"time")+at;}}
        foreach(var raw in Items(copy,"tracks")){var track=raw.AsGodotDictionary();track["id"]=ids[track["id"]];track["output"]=Get(ids,S(track,"output"),"");track["group"]=Get(ids,S(track,"group"),"");foreach(var sendRaw in Get(track,"sends",new GArray()).AsGodotArray()){var send=sendRaw.AsGodotDictionary();send["target"]=Get(ids,S(send,"target"),"");}foreach(string key in new[]{"frozen_track","frozen_source","freeze_members"})track.Remove(key);track["locked"]=false;ShiftCurves(track);foreach(var effect in Get(track,"effects",new GArray()).AsGodotArray())ShiftCurves(effect.AsGodotDictionary());}
        using var edits=new AudioEditSessionOperations();var clips=Items(copy,"clips");var actors=Items(copy,"actors");for(int i=0;i<clips.Count;i++){var clip=clips[i].AsGodotObject();var actor=actors[i].AsGodotObject();SourceTiming(actor,bundle,edits);clip.Set("id",ids[clip.Get("id")]);clip.Set("actor_id",ids[clip.Get("actor_id")]);actor.Set("id",ids[actor.Get("id")]);clip.Set("start_time",clip.Get("start_time").AsDouble()+at);var values=actor.Get("values").AsGodotDictionary();values[new StringName("track_id")]=Get(ids,S(values,"track_id"),"");actor.Set("parent_id",Get(ids,actor.Get("parent_id").AsString(),""));}var candidate=session.Get("document").AsGodotObject().Call("snapshot").As<RefCounted>();foreach(string field in new[]{"tracks","actors","clips"})Append(Items(candidate,field),Items(copy,field));errors=candidate.Call("validate").AsStringArray();if(errors.Length>0)return "Bundle insertion rejected: "+string.Join("\n",errors);session.Call("action","Insert layer bundle",Callable.From(()=>{var document=session.Get("document").AsGodotObject();foreach(string field in new[]{"tracks","actors","clips"})Append(Items(document,field),Items(copy,field));var selected=Items(session,"selected_ids");selected.Clear();foreach(var raw in clips)selected.Add(raw.AsGodotObject().Get("id"));if(Items(copy,"tracks").Count>0)session.Set("selected_track",Items(copy,"tracks")[0].AsGodotDictionary()["id"]);}));session.EmitSignal("selection_changed");return "";
    }
    public string rebase_owner(Settings owner,double origin)
    {
        var curves=Get(owner,"automation",new Settings()).AsGodotDictionary();using var effects=new AudioEffectsOperations();foreach(var parameter in curves.Keys){var points=curves[parameter].AsGodotArray();if(points.Count==0)continue;string curve="linear";for(int i=0;i<points.Count;i++){var point=points[i].AsGodotDictionary();if(N(point,"time")<=origin){curve=S(point,"curve","linear");if(curve=="smooth"&&i+1<points.Count&&N(point,"time")<origin&&N(points[i+1].AsGodotDictionary(),"time")>origin)return "A smooth bus/effect curve crosses the bundle origin. Split/bake it first; its easing will not be silently changed.";}}double fallback=N(Get(owner,"parameters",owner).AsGodotDictionary(),parameter.AsString());var rebased=new GArray{new Settings{["time"]=0.0,["value"]=effects.automation_value(points,origin,fallback),["curve"]=curve}};foreach(var raw in points){var point=raw.AsGodotDictionary();if(N(point,"time")>origin){var copy=point.Duplicate(true);copy["time"]=N(point,"time")-origin;rebased.Add(copy);}}curves[parameter]=rebased;}return "";
    }
}
